from collections import defaultdict

class Solution:
    def longestSubarray(self, nums, k):
        freq = defaultdict(int)
        left = 0
        repeated = 0
        ans = 0

        for right in range(len(nums)):
            freq[nums[right]] += 1

            if freq[nums[right]] == 2:
                repeated += 1

            while repeated > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 1:
                    repeated -= 1
                left += 1

            ans = max(ans, right - left + 1)

        return ans

class Solution:
    def earliestFinishTime(self, landStartTime, landDuration, waterStartTime, waterDuration):
        ans = float('inf')

        for i in range(len(landStartTime)):
            land_end = landStartTime[i] + landDuration[i]

            for j in range(len(waterStartTime)):
                start = max(land_end, waterStartTime[j])
                ans = min(ans, start + waterDuration[j])

        for i in range(len(waterStartTime)):
            water_end = waterStartTime[i] + waterDuration[i]

            for j in range(len(landStartTime)):
                start = max(water_end, landStartTime[j])
                ans = min(ans, start + landDuration[j])

        return ans

class Solution:
    def maxWeight(self, weights):
        weights.sort(reverse=True)
        n = len(weights)

        bag1 = sum(weights[:n//2])
        bag2 = sum(weights[n//2:])

        return abs(bag1 - bag2)

class Solution:
    def maxBalancedShipments(self, weight):
        ans = 0
        mn = weight[0]

        for i in range(1, len(weight)):
            if weight[i] > mn:
                ans += 1
                mn = float('inf')
            else:
                mn = min(mn, weight[i])

        return ans

class Solution:
    def trionic(self, nums):
        n = len(nums)
        inc = [1] * n
        dec = [1] * n

        for i in range(1, n):
            if nums[i] > nums[i - 1]:
                inc[i] = inc[i - 1] + 1

        for i in range(n - 2, -1, -1):
            if nums[i] > nums[i + 1]:
                dec[i] = dec[i + 1] + 1

        ans = 0
        for i in range(n):
            ans = max(ans, inc[i] + dec[i] - 1)

        return ans

class Solution:
    def nextPalindrome(self, num):
        s = str(num + 1)

        while True:
            if s == s[::-1]:
                return int(s)
            s = str(int(s) + 1)

class Solution:
    def sortThreats(self, threats):
        threats.sort(key=lambda x: (-x[1], -x[2]))
        return threats
